  try { if ($script:Writer) { $script:Writer.Flush(); $script:Writer.Dispose() } } catch { }
  $script:Writer = $null
  # 退出码放在 finally 里：中断会停掉管道，写在 try 之后的 exit 不会被执行。
  exit $script:ExitCode
}

